args.content:
:root {
  --primary: #2c5282;
  --secondary: #4a6fa1;
  --bg: #f7fafc;
  --text: #1a202c;
  --subtle: #718096;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: 'Georgia', serif;
  line-height: 1.7;
  color: var(--text);
  background: var(--bg);
  max-width: 720px;
  margin: 0 auto;
  padding: 2rem 1.5rem;
}

header {
  text-align: center;
  margin-bottom: 3rem;
  padding-bottom: 2rem;
  border-bottom: 1px solid #e2e8f0;
}

h1 {
  font-size: 2.25rem;
  font-weight: 400;
  letter-spacing: 0.02em;
  color: var(--primary);
  margin-bottom: 0.5rem;
}

.tagline {
  font-style: italic;
  color: var(--subtle);
  font-size: 1.1rem;
}

h2 {
  font-size: 1.25rem;
  font-weight: 600;
  color: var(--primary);
  margin-bottom: 1rem;
  margin-top: 2.5rem;
}

section {
  margin-bottom: 2rem;
}

.intro p {
  margin-bottom: 1rem;
  font-size: 1.05rem;
}

ul {
  list-style: none;
  padding-left: 0;
}

li {
  margin-bottom: 0.75rem;
  padding-left: 1.25rem;
  position: relative;
}

li::before {
  content: "—";
  position: absolute;
  left: 0;
  color: var(--secondary);
}

a {
  color: var(--secondary);
  text-decoration: none;
  border-bottom: 1px solid transparent;
  transition: border-color 0.2s;
}

a:hover {
  border-bottom-color: var(--secondary);
}

footer {
  margin-top: 4rem;
  padding-top: 1.5rem;
  border-top: 1px solid #e2e8f0;
  text-align: center;
  color: var(--subtle);
  font-size: 0.875rem;
}

@media (max-width: 480px) {
  body {
    padding: 1.5rem 1rem;
  }

  h1 {
    font-size: 1.75rem;
  }
}
